/**
 * Gesto Nativo de Swipe-Down para Bajar el Bottom Sheet
 */
function initBottomSheetPullDownDismiss() {
    const sheet = document.getElementById('sensExerciseModalSheet');
    if (!sheet || sheet._hasPullDownBound) return;
    sheet._hasPullDownBound = true;

    let startY = 0;
    let currentY = 0;
    let isDragging = false;
    let startTime = 0;

    const onTouchStart = (e) => {
        if (!e.touches || e.touches.length === 0) return;
        if (sheet.scrollTop <= 6) {
            startY = e.touches[0].clientY;
            currentY = startY;
            startTime = Date.now();
            isDragging = true;
            sheet.style.transition = 'none';
        }
    };

    const onTouchMove = (e) => {
        if (!isDragging || !e.touches || e.touches.length === 0) return;
        currentY = e.touches[0].clientY;
        const deltaY = currentY - startY;
        if (deltaY > 0 && sheet.scrollTop <= 6) {
            sheet.style.transform = `translateY(${deltaY}px)`;
        }
    };

    const onTouchEnd = () => {
        if (!isDragging) return;
        isDragging = false;
        const deltaY = currentY - startY;
        const deltaTime = Date.now() - startTime;
        const velocity = deltaY / (deltaTime || 1);

        if (deltaY > 110 || (velocity > 0.45 && deltaY > 40)) {
            sheet.style.transition = 'transform 0.22s cubic-bezier(0.16, 1, 0.3, 1)';
            sheet.style.transform = 'translateY(100%)';
            setTimeout(() => {
                handleAttemptExitExerciseModal();
            }, 200);
        } else {
            sheet.style.transition = 'transform 0.24s cubic-bezier(0.16, 1, 0.3, 1)';
            sheet.style.transform = 'translateY(0)';
        }
    };

    sheet.addEventListener('touchstart', onTouchStart, { passive: true });
    sheet.addEventListener('touchmove', onTouchMove, { passive: true });
    sheet.addEventListener('touchend', onTouchEnd, { passive: true });
}

/**
 * Lógica de Guardado y Salida con Confirmación
 */
function saveAndFinishExercise(silent = false) {
    const currentExId = modalExerciseState.exId;
    const currentDayKey = modalExerciseState.dayKey || AppState.currentDay || 'day1';
    const isFuture = isFutureDate(currentDayKey);
    const dayDate = getDateFromDayKey(currentDayKey);

    if (currentExId && !isFuture) {
        const athId = getActiveAthleteId();
        const data = getCoachAthleteWorkoutData(athId);
        const day = (data && data[currentDayKey]) ? data[currentDayKey] : null;
        if (day && Array.isArray(day.exercises)) {
            const ex = day.exercises.find(e => e.id === currentExId);
            if (ex) {
                const anyDone = modalExerciseState.setsData && modalExerciseState.setsData.some(s => s.completed);
                ex.completed = Boolean(anyDone);
                const allDone = day.exercises.length > 0 && day.exercises.every(e => e.completed);
                day.completed = allDone;
                day.durationMinutes = day.durationMinutes || Math.max(30, day.exercises.length * 9);
                saveAthleteDayWorkoutStatus(athId, currentDayKey, { 
                    exercises: day.exercises,
                    completed: allDone,
                    durationMinutes: day.durationMinutes
                });
                if (!silent && typeof showSensToast === 'function') {
                    showSensToast(`✓ Progreso de ${ex.name} guardado con éxito.`, 'champagne', 2600);
                }
            }
        }
    }
    AppState.selectedDate = dayDate;
    AppState.currentDay = currentDayKey;
    closeExerciseExecutionModalForce();
}

function handleAttemptExitExerciseModal() {
    const hasCheckedSets = modalExerciseState.setsData && modalExerciseState.setsData.some(s => s.completed);
    if (!hasCheckedSets) {
        saveAndFinishExercise(true);
        return;
    }

    const exitModal = document.getElementById('sensExitConfirmModal');
    if (exitModal) {
        exitModal.style.display = 'flex';
    } else {
        saveAndFinishExercise(false);
    }
}

function closeExerciseExecutionModalForce() {
    const exitModal = document.getElementById('sensExitConfirmModal');
    if (exitModal) exitModal.style.display = 'none';

    const backdrop = document.getElementById('sensExerciseModalBackdrop');
    const sheet = document.getElementById('sensExerciseModalSheet');
    if (sheet) {
        sheet.style.transform = '';
        sheet.style.transition = '';
    }
    if (backdrop) backdrop.style.display = 'none';
    document.body.style.overflow = '';

    clearInterval(masterTimerState.interval);
    masterTimerState.mode = 'idle';

    const modalVideo = document.getElementById('modalExVideo');
    if (modalVideo) modalVideo.pause();

    const currentDayKey = modalExerciseState.dayKey || AppState.currentDay || 'day1';
    const targetDate = getDateFromDayKey(currentDayKey);
    renderWorkoutDay(currentDayKey);
    renderWorkoutDaysNav();
    if (typeof renderDynamicWeekStrip === 'function') renderDynamicWeekStrip();

    if (typeof syncAllStreakAndPillTelemetry === 'function') {
        syncAllStreakAndPillTelemetry(targetDate);
    } else {
        if (typeof SensDailyStreakManager !== 'undefined') {
            SensDailyStreakManager.evaluateDay(targetDate);
        }
        if (typeof updateSensStreakCard === 'function') {
            updateSensStreakCard(targetDate);
        }
    }
}

window.closeExerciseExecutionModal = function() {
    handleAttemptExitExerciseModal();
};

function initExitConfirmationListeners() {
    const saveBtn = document.getElementById('btnExitConfirmSave');
    const discardBtn = document.getElementById('btnExitConfirmDiscard');
    const cancelBtn = document.getElementById('btnExitConfirmCancel');
    const modal = document.getElementById('sensExitConfirmModal');

    if (!modal || modal._hasExitBound) return;
    modal._hasExitBound = true;

    if (saveBtn) {
        saveBtn.addEventListener('click', () => {
            saveAndFinishExercise(false);
        });
    }

    if (discardBtn) {
        discardBtn.addEventListener('click', () => {
            closeExerciseExecutionModalForce();
        });
    }

    if (cancelBtn) {
        cancelBtn.addEventListener('click', () => {
            modal.style.display = 'none';
            const sheet = document.getElementById('sensExerciseModalSheet');
            if (sheet) {
                sheet.style.transition = 'transform 0.24s cubic-bezier(0.16, 1, 0.3, 1)';
                sheet.style.transform = 'translateY(0)';
            }
        });
    }
}

// Wire up events del Modal
document.addEventListener('DOMContentLoaded', () => {
    const closeBtn = document.getElementById('btnCloseExerciseModal');
    const finishBtn = document.getElementById('btnModalFinishExercise');
    const backdrop = document.getElementById('sensExerciseModalBackdrop');

    if (closeBtn) closeBtn.addEventListener('click', () => handleAttemptExitExerciseModal());
    if (finishBtn) {
        finishBtn.addEventListener('click', () => {
            saveAndFinishExercise(false);
        });
    }
    if (backdrop) {
        backdrop.addEventListener('click', (e) => {
            if (e.target === backdrop) handleAttemptExitExerciseModal();
        });
    }
});

function startRestTimer(seconds) {
    stopRestTimer();
    const widget = document.getElementById('floatingRestTimer');
    if (!widget) return;

    AppState.remainingSeconds = seconds;
    widget.classList.add('active');
    updateTimerDisplay();

    AppState.activeTimerInterval = setInterval(() => {
        AppState.remainingSeconds--;
        if (AppState.remainingSeconds <= 0) {
            stopRestTimer();
            playBeep(880, 0.4); // tono agudo de fin de descanso
            showSensToast('Descanso completado. Preparate para el próximo set.', 'champagne', 3400);
        } else {
            updateTimerDisplay();
        }
    }, 1000);
}

function stopRestTimer() {
    if (AppState.activeTimerInterval) {
        clearInterval(AppState.activeTimerInterval);
        AppState.activeTimerInterval = null;
    }
    const widget = document.getElementById('floatingRestTimer');
    if (widget) widget.classList.remove('active');
}

function updateTimerDisplay() {
    const display = document.getElementById('timerDisplay');
    if (!display) return;
    const mins = Math.floor(AppState.remainingSeconds / 60);
    const secs = AppState.remainingSeconds % 60;
    display.textContent = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
}

function openVideoModal(title, cue) {
    const modal = document.getElementById('videoModal');
    const modalTitle = document.getElementById('videoModalTitle');
    const videoPlayer = document.getElementById('videoModalPlayer');
    if (modal && modalTitle) {
        modalTitle.textContent = title || 'Demostración Técnica';
        const cueParagraph = modal.querySelector('p:last-of-type');
        if (cueParagraph && cue) {
            cueParagraph.innerHTML = `<strong>Consejo de Nico:</strong> ${cue}`;
        }
        const videoSkeleton = document.getElementById('videoModalPlayerSkeleton');
        if (videoPlayer) {
            if (videoSkeleton) videoSkeleton.classList.remove('is-hidden');
            videoPlayer.src = SENS_EXERCISE_MOCKUP_VIDEO;
            videoPlayer.load();
            videoPlayer.play().catch(() => {});
            if (typeof attachVideoSkeleton === 'function') {
                attachVideoSkeleton(videoPlayer, videoSkeleton);
            }
        }
        modal.classList.add('active');
    }
}

// Generador de audio nativo con Web Audio API para timers
function playBeep(freq = 440, duration = 0.2) {
    try {
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + duration);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + duration);
    } catch (e) {
        // Silencioso si no hay soporte o permisos
    }
}

