/**
 * Actualiza los badges de racha en las 3 cards principales del Inicio (Training, Nutrición, Balance):
 * - Entrenamiento: ej. "2/5 ejercicios" (Champagne Gold), "5/5 ejercicios ✓" (Emerald Green) o "Descanso Activo ✓"
 * - Nutrición: ej. "800/1.800 cal" (Champagne Gold), "1.850/1.950 cal ✓" (Emerald Green) o "Superado ✕" (Red)
 * - Balance / Actividad: ej. "200 / 10.000 pasos ó 20/30 min corriendo" (Champagne Gold) o "... ✓" (Emerald Green)
 */
function updateHomeCardsStreakPills(targetDate = null, athId = null) {
    if (!targetDate) targetDate = AppState.selectedDate || new Date();
    if (!athId) athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';

    const sDate = (targetDate instanceof Date) ? targetDate : new Date(targetDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const targetMidnight = new Date(sDate);
    targetMidnight.setHours(0, 0, 0, 0);
    const isPastDay = targetMidnight < today;
    const isFutureDay = targetMidnight > today;

    if (typeof SensDailyStreakManager === 'undefined') return;

    const evalResult = SensDailyStreakManager.evaluateDay(sDate, athId);
    if (!evalResult || !evalResult.current) return;
    const dayRec = evalResult.current;

    const updatePill = (elId, statusClass, text, title) => {
        const el = document.getElementById(elId);
        if (!el) return;
        el.className = `sens-card-streak-pill ${statusClass}`;
        el.setAttribute('title', title || text);
        el.onclick = () => {
            if (typeof window.scrollToStreakCard === 'function') {
                window.scrollToStreakCard();
            }
        };
        el.innerHTML = `<span class="streak-pill-dot"></span><span class="streak-pill-text">${text}</span>`;
    };

    // 1. Pilar Entrenamiento
    const wRec = dayRec.workout || {};
    let wStatus = 'in-progress';
    let wText = '0/0 ejercicios';

    if (isFutureDay) {
        const dayKey = (typeof getDayKeyFromDate === 'function') ? getDayKeyFromDate(sDate) : 'day1';
        const workoutData = (typeof getCoachAthleteWorkoutData === 'function') ? getCoachAthleteWorkoutData(athId) : null;
        const dayWorkout = (workoutData && workoutData[dayKey]) ? workoutData[dayKey] : null;
        const isRest = dayWorkout?.modality === 'descanso';
        const total = (dayWorkout && Array.isArray(dayWorkout.exercises)) ? dayWorkout.exercises.length : 0;
        wStatus = 'in-progress';
        wText = isRest ? 'Descanso Programado' : (total > 0 ? `0/${total} ejercicios` : '0/0 ejercicios');
    } else if (wRec.isRestDay) {
        wStatus = 'done';
        wText = 'Descanso Activo ✓';
    } else if (wRec.done) {
        wStatus = 'done';
        const total = wRec.totalExercises || 0;
        wText = total > 0 ? `${total}/${total} ejercicios ✓` : 'Sesión completada ✓';
    } else {
        let completed = wRec.completedExercises;
        let total = wRec.totalExercises;
        if (typeof completed !== 'number' || typeof total !== 'number' || (completed === 0 && total === 0)) {
            const match = String(wRec.metric || '').match(/(\d+)\s*de\s*(\d+)/i);
            if (match) {
                completed = parseInt(match[1], 10);
                total = parseInt(match[2], 10);
            } else {
                const dayKey = (typeof getDayKeyFromDate === 'function') ? getDayKeyFromDate(sDate) : 'day1';
                const workoutData = (typeof getCoachAthleteWorkoutData === 'function') ? getCoachAthleteWorkoutData(athId) : null;
                const dayWorkout = (workoutData && workoutData[dayKey]) ? workoutData[dayKey] : null;
                if (dayWorkout && Array.isArray(dayWorkout.exercises)) {
                    total = dayWorkout.exercises.length;
                    completed = dayWorkout.exercises.filter(e => e.completed).length;
                } else {
                    completed = 0;
                    total = 0;
                }
            }
        }
        if (isPastDay) {
            wStatus = 'lost';
            wText = total > 0 ? `${completed}/${total} ejercicios ✕` : 'Sesión no realizada ✕';
        } else {
            wStatus = 'in-progress';
            wText = total > 0 ? `${completed}/${total} ejercicios` : '0/0 ejercicios';
        }
    }

    updatePill('dashWorkoutStreakPill', wStatus, wText, 'Progreso de entrenamiento para la racha diaria');
    updatePill('dashWorkoutRestStreakPill', 'done', 'Descanso Activo ✓', 'Día de recuperación celular para la racha diaria');

    // 2. Pilar Nutrición
    const nRec = dayRec.nutrition || {};
    let nStatus = 'in-progress';
    let nText = '0/0 cal';
    const consumed = nRec.consumed || 0;
    const target = nRec.target || 1950;
    const consumedStr = consumed.toLocaleString('es-AR');
    const targetStr = target.toLocaleString('es-AR');

    if (isFutureDay) {
        nStatus = 'in-progress';
        nText = `0 / ${targetStr} cal`;
    } else if (nRec.done) {
        nStatus = 'done';
        nText = `${consumedStr}/${targetStr} cal ✓`;
    } else if (nRec.status === 'exceeded') {
        nStatus = 'exceeded';
        nText = `${consumedStr}/${targetStr} cal • Superado ✕`;
    } else {
        if (isPastDay) {
            nStatus = 'lost';
            nText = consumed > 0 ? `${consumedStr}/${targetStr} cal ✕` : 'Sin registro calórico ✕';
        } else {
            nStatus = 'in-progress';
            nText = `${consumedStr}/${targetStr} cal`;
        }
    }

    updatePill('dashNutriStreakPill', nStatus, nText, 'Progreso calórico para la racha diaria (-20% a +10% del objetivo)');

    // 3. Pilar Balance Energético / Actividad (Formato Conciso Quiet Luxury)
    const cRec = dayRec.cardio || {};
    let cStatus = 'in-progress';
    let cText = '0 / 10k pasos';

    const steps = cRec.steps || 0;
    const cardioMinutes = cRec.cardioMinutes || 0;
    const cardioType = cRec.cardioType || 'caminata';
    const targetCardioMin = (cardioType === 'caminata') ? 90 : 30;

    let cardioLabel = 'cardio';
    if (cardioType === 'running') cardioLabel = 'running';
    else if (cardioType === 'caminata') cardioLabel = 'caminata';
    else if (cardioType === 'bici') cardioLabel = 'bici';
    else if (cardioType === 'natacion') cardioLabel = 'natación';
    else cardioLabel = cardioType;

    const formatSteps = (num) => {
        if (!num || num === 0) return '0';
        if (num >= 1000) {
            const k = (num / 1000).toFixed(1).replace('.0', '');
            return `${k}k`;
        }
        return String(num);
    };

    const stepsFormatted = formatSteps(steps);

    if (isFutureDay) {
        cStatus = 'in-progress';
        cText = '0 / 10k pasos';
    } else if (cRec.done) {
        cStatus = 'done';
        if (steps >= 10000) {
            cText = `${stepsFormatted} / 10k pasos ✓`;
        } else {
            cText = `${cardioMinutes}m / ${targetCardioMin}m ${cardioLabel} ✓`;
        }
    } else if (isPastDay) {
        cStatus = 'lost';
        if (steps > 0) {
            cText = `${stepsFormatted} / 10k pasos ✕`;
        } else if (cardioMinutes > 0) {
            cText = `${cardioMinutes}m / ${targetCardioMin}m ✕`;
        } else {
            cText = '0 / 10k pasos ✕';
        }
    } else {
        cStatus = 'in-progress';
        if (cardioMinutes > 0 && steps === 0) {
            cText = `${cardioMinutes}m / ${targetCardioMin}m ${cardioLabel}`;
        } else if (steps > 0 && cardioMinutes > 0) {
            cText = `${stepsFormatted} pasos • ${cardioMinutes}m`;
        } else {
            cText = `${stepsFormatted} / 10k pasos`;
        }
    }

    updatePill('dashActivityStreakPill', cStatus, cText, 'Objetivo de pasos (10k) o cardio (90m caminata / 30m cardio) para la racha diaria');
    updatePill('dashActivityLoggerStreakPill', cStatus, cText, 'Objetivo de pasos o cardio para la racha diaria');
}
window.updateHomeCardsStreakPills = updateHomeCardsStreakPills;

window.stepDailySteps = function(delta) {
    const input = document.getElementById('dashStepsInput');
    if (!input) return;
    const current = parseInt(input.value, 10) || 0;
    const nextVal = Math.max(0, current + delta);
    input.value = nextVal;
    document.querySelectorAll('.sens-act-quick-chip').forEach(c => {
        const chipVal = parseInt(c.textContent.replace('.', '').replace(',', ''), 10) || 0;
        c.classList.toggle('active', chipVal > 0 && chipVal === nextVal);
    });
    window.handleStepsInputChange(nextVal);
};

window.quickSetDailySteps = function(steps) {
    const input = document.getElementById('dashStepsInput');
    if (input) input.value = steps;
    document.querySelectorAll('.sens-act-quick-chip').forEach(c => {
        const chipVal = parseInt(c.textContent.replace('.', '').replace(',', ''), 10) || 0;
        c.classList.toggle('active', chipVal > 0 && chipVal === steps);
    });
    window.handleStepsInputChange(steps);
};

window.handleStepsInputChange = function(val) {
    const steps = Math.max(0, parseInt(val, 10) || 0);
    document.querySelectorAll('.sens-act-quick-chip').forEach(c => {
        const chipVal = parseInt(c.textContent.replace('.', '').replace(',', ''), 10) || 0;
        c.classList.toggle('active', chipVal > 0 && chipVal === steps);
    });

    const targetDate = AppState.selectedDate || new Date();
    updateObjectiveCardData(targetDate, true);

    const saveBtnText = document.getElementById('btnSaveActivityText');
    if (saveBtnText && saveBtnText.textContent !== '✓ Actividad Guardada') {
        saveBtnText.textContent = 'Guardar Actividad & Balance';
    }
};

window.stepDailyCardio = function(delta) {
    const input = document.getElementById('dashCardioInput');
    if (!input) return;
    const current = parseInt(input.value, 10) || 0;
    const nextVal = Math.max(0, current + delta);
    input.value = nextVal;
    window.handleCardioInputChange(nextVal);
};

window.handleCardioInputChange = function(val) {
    const targetDate = AppState.selectedDate || new Date();
    updateObjectiveCardData(targetDate, true);

    const saveBtnText = document.getElementById('btnSaveActivityText');
    if (saveBtnText && saveBtnText.textContent !== '✓ Actividad Guardada') {
        saveBtnText.textContent = 'Guardar Actividad & Balance';
    }
};

window.setCardioType = function(type, rate, btn) {
    document.querySelectorAll('#dashCardioTypesGrid .sens-cardio-type-btn').forEach(b => b.classList.remove('active'));
    if (btn) {
        btn.classList.add('active');
    } else {
        const match = document.querySelector(`#dashCardioTypesGrid .sens-cardio-type-btn[data-type="${type}"]`);
        if (match) match.classList.add('active');
    }
    
    const targetDate = AppState.selectedDate || new Date();
    updateObjectiveCardData(targetDate, true);

    const saveBtnText = document.getElementById('btnSaveActivityText');
    if (saveBtnText && saveBtnText.textContent !== '✓ Actividad Guardada') {
        saveBtnText.textContent = 'Guardar Actividad & Balance';
    }
};

window.saveActivityChanges = function(isExplicitSave = false) {
    const targetDate = AppState.selectedDate || new Date();
    if (isExplicitSave && isFutureDate(targetDate)) {
        if (typeof showSensToast === 'function') {
            showSensToast('No es posible registrar actividad de fechas futuras.', 'champagne', 2500);
        }
        return;
    }
    const dateKey = getFormattedDateKey(targetDate);
    const athId = getActiveAthleteId();
    
    const stepsInput = document.getElementById('dashStepsInput');
    const cardioInput = document.getElementById('dashCardioInput');
    const activeBtn = document.querySelector('#dashCardioTypesGrid .sens-cardio-type-btn.active');
    
    const steps = stepsInput ? (parseInt(stepsInput.value, 10) || 0) : 0;
    const cardioMinutes = cardioInput ? (parseInt(cardioInput.value, 10) || 0) : 0;
    const cardioType = activeBtn ? activeBtn.getAttribute('data-type') : 'caminata';
    const cardioRate = activeBtn ? parseFloat(activeBtn.getAttribute('data-rate')) || 6.5 : 6.5;

    // Detectar si el atleta ya había cumplido racha de actividad hoy
    let wasCardioDone = false;
    if (isExplicitSave && typeof SensDailyStreakManager !== 'undefined') {
        const records = SensDailyStreakManager.getAllRecords(athId);
        if (records && records[dateKey] && records[dateKey].cardio && records[dateKey].cardio.done) {
            wasCardioDone = true;
        }
    }
    
    if (isExplicitSave) {
        saveAthleteActivityLog(athId, dateKey, {
            steps,
            cardioMinutes,
            cardioType,
            cardioRate
        });
    }
    
    updateObjectiveCardData(targetDate, !isExplicitSave);

    if (isExplicitSave) {
        // Actualizar racha y cards principales
        if (typeof syncAllStreakAndPillTelemetry === 'function') {
            syncAllStreakAndPillTelemetry(targetDate);
        } else {
            if (typeof updateSensStreakCard === 'function') {
                updateSensStreakCard(targetDate);
            }
            if (typeof updateHomeCardsStreakPills === 'function') {
                updateHomeCardsStreakPills(targetDate, athId);
            }
        }

        const saveBtnText = document.getElementById('btnSaveActivityText');
        if (saveBtnText) {
            saveBtnText.innerHTML = `✓ Actividad Guardada`;
            setTimeout(() => {
                const btn = document.getElementById('btnSaveActivityText');
                if (btn) btn.textContent = 'Guardar Actividad & Balance';
            }, 2400);
        }

        // Evaluar si califica para racha de pasos & cardio (10.000 pasos ó 90m caminata ó 30m otro cardio)
        const qualifies = (steps >= 10000 || (cardioType === 'caminata' && cardioMinutes >= 90) || (cardioType !== 'caminata' && cardioMinutes >= 30));

        if (qualifies) {
            const streakDays = (typeof SensDailyStreakManager !== 'undefined') ? SensDailyStreakManager.calculateStreak(athId) : 1;
            const evalResult = (typeof SensDailyStreakManager !== 'undefined') ? SensDailyStreakManager.evaluateDay(targetDate, athId) : null;
            const isAllThreeDone = (evalResult?.current?.completedCount === 3);

            if (isAllThreeDone) {
                if (typeof window.showSensCelebrationToast === 'function') {
                    window.showSensCelebrationToast(
                        '¡DÍA PERFECTO 100%!',
                        'Fuerza, Nutrición y Balance completados hoy • Racha Máxima',
                        '"La consistencia implacable en los tres pilares biológicos te posiciona en el 1% de disciplina y rendimiento celular."'
                    );
                }
            } else {
                if (typeof window.showSensCelebrationToast === 'function') {
                    window.showSensCelebrationToast(
                        '¡META AERÓBICA CONQUISTADA!',
                        `${steps >= 10000 ? `${steps.toLocaleString('es-AR')} Pasos` : `${cardioMinutes}m de ${cardioType}`} • Racha SENS Activa`,
                        '"El gasto activo diario optimiza tu partición de nutrientes, mejora la sensibilidad a la insulina y eleva tu tasa metabólica."'
                    );
                }
            }
        } else {
            if (wasCardioDone) {
                if (typeof showSensToast === 'function') {
                    showSensToast('Perdiste el objetivo de racha de actividad de hoy (mínimo 10.000 pasos ó 30m cardio).', 'warning', 4500);
                }
            } else {
                const missingSteps = Math.max(0, 10000 - steps);
                const msg = (steps > 0 || cardioMinutes > 0)
                    ? `✓ Actividad guardada (${steps.toLocaleString('es-AR')} pasos • ${cardioMinutes}m). Faltan ${missingSteps.toLocaleString('es-AR')} pasos para sumar racha diaria.`
                    : `✓ Balance guardado. Completá pasos o cardio para sumar a tu racha diaria.`;
                if (typeof showSensToast === 'function') {
                    showSensToast(msg, 'champagne', 4200);
                }
            }
            try { if (navigator.vibrate) navigator.vibrate([30, 40, 30]); } catch (e) {}
        }
    }
};

/**
 * Verifica si una fecha tiene entrenamiento marcado como completado en el historial persistido
 */
function isDateInCompletedWorkouts(dateKey) {
    try {
        const stored = JSON.parse(localStorage.getItem('sens_completed_workout_dates') || '[]');
        if (Array.isArray(stored)) {
            if (stored.includes(dateKey)) return true;
            const parts = String(dateKey).split('-');
            if (parts.length === 3) {
                const dayNum = parseInt(parts[2], 10);
                if (stored.includes(dayNum)) return true;
            }
        }
    } catch (e) {}
    return false;
}
window.isDateInCompletedWorkouts = isDateInCompletedWorkouts;

/**
 * Calcula las métricas metabólicas del día seleccionado (Ecuación real de balance energético)
 */
function getDailyMetabolicMetrics(targetDate) {
    const athId = getActiveAthleteId();
    const isDemo = (athId === 'usr-vip-001' || athId === 'mock_vip');
    const profile = (AppState.profile && AppState.profile.id === athId) ? AppState.profile : (AppState.profile || {});
    const anamnesis = AppState.anamnesis || {};

    const weightRaw = profile.current_weight || anamnesis.weight;
    const weight = weightRaw ? parseFloat(weightRaw) : (isDemo ? 78.5 : 70.0);
    const bmr = (typeof calculateAthleteBMR === 'function') ? calculateAthleteBMR(athId) : Math.round(weight * 22);

    const dateKey = getFormattedDateKey(targetDate);
    const actLog = getAthleteActivityLog(athId, dateKey);

    const dayKey = getDayKeyFromDate(targetDate);
    const data = getCoachAthleteWorkoutData(athId);
    let dayData = (data && data[dayKey]) ? data[dayKey] : {};
    if (!dayData || !dayData.exercises) {
        if (data && data.calendar_schedule && data.calendar_schedule[dateKey]) {
            dayData = data.calendar_schedule[dateKey];
        } else if (typeof WORKOUT_DAYS_DATA !== 'undefined' && WORKOUT_DAYS_DATA[dayKey]) {
            dayData = WORKOUT_DAYS_DATA[dayKey];
        }
    }

    const hasWorkout = Boolean(dayData.exercises && dayData.exercises.length > 0 && dayData.modality !== 'descanso');
    const isWorkoutDone = Boolean(dayData.completed || isDateInCompletedWorkouts(dateKey));

    // Gasto por entrenamiento de fuerza REAL (0 si no se entrenó o descanso)
    let workoutBurn = 0;
    let completedExCount = 0;
    let totalExCount = 0;

    if (dayData && Array.isArray(dayData.exercises) && dayData.exercises.length > 0 && dayData.modality !== 'descanso') {
        totalExCount = dayData.exercises.length;
        completedExCount = dayData.exercises.filter(e => e.completed).length;
    }

    if (isWorkoutDone) {
        workoutBurn = 380;
    } else if (completedExCount > 0 && totalExCount > 0) {
        workoutBurn = Math.round((completedExCount / totalExCount) * 380);
    } else {
        workoutBurn = 0;
    }

    // Pasos del día (NEAT) - De entrada marca 0 si no se ha guardado
    let dailySteps = (actLog && actLog.steps !== undefined) ? Number(actLog.steps) : 0;
    if (dailySteps === 0) {
        const legacySteps = localStorage.getItem(`sens_steps_${dateKey}`);
        if (legacySteps !== null && !isNaN(parseInt(legacySteps, 10))) {
            dailySteps = Math.max(0, parseInt(legacySteps, 10));
        }
    }
    const stepsBurn = Math.round(dailySteps * (weight * 0.00052));

    // Cardio del día
    const cardioMinutes = (actLog && actLog.cardioMinutes !== undefined) ? Number(actLog.cardioMinutes) : 0;
    const cardioRate = Number(actLog.cardioRate) || 6.5;
    const cardioBurn = Math.round(cardioMinutes * cardioRate);

    // Gasto Activo Total
    const activeBurn = workoutBurn + stepsBurn + cardioBurn;
    const tdee = bmr + activeBurn;

    // Ingesta calórica: objetivo prescripto vs real consumido
    const prescribedCalories = (typeof getAthletePrescribedCalories === 'function')
        ? getAthletePrescribedCalories(athId, targetDate)
        : (profile.daily_calories ? parseInt(profile.daily_calories, 10) : 1950);

    const consumedCalories = (typeof getAthleteConsumedCalories === 'function')
        ? getAthleteConsumedCalories(athId, targetDate)
        : 0;

    const targetIntake = consumedCalories;
    const netBalance = targetIntake - tdee;

    return {
        weight,
        bmr,
        dailySteps,
        stepsBurn,
        cardioMinutes,
        cardioType: actLog.cardioType || 'caminata',
        cardioRate,
        cardioBurn,
        workoutBurn,
        hasWorkout,
        isWorkoutDone,
        completedExCount,
        totalExCount,
        activeBurn,
        tdee,
        targetIntake,
        prescribedCalories,
        consumedCalories,
        netBalance
    };
}
window.getDailyMetabolicMetrics = getDailyMetabolicMetrics;

/**
 * Renderiza el gráfico semanal interactivo con Chart.js en #dashWeeklyBalanceChart
 */
/**
 * Renderiza el gráfico semanal interactivo con Chart.js en #dashWeeklyBalanceChart
 */
function renderWeeklyBalanceChart(selectedDate = new Date()) {
    const canvas = document.getElementById('dashWeeklyBalanceChart');
    if (!canvas || typeof Chart === 'undefined' || canvas.offsetParent === null) return;

    if (!AppState.activeWeekStart) {
        AppState.activeWeekStart = getMonday(new Date());
    }

    const dayLabels = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'];
    const weekStats = [];
    const barColors = [];
    const borderColors = [];

    const profile = AppState.profile || {};
    const userGoal = profile.goal || 'fat_loss';
    const isMuscleGain = userGoal === 'muscle_gain';

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    for (let i = 0; i < 7; i++) {
        const d = new Date(AppState.activeWeekStart);
        d.setDate(AppState.activeWeekStart.getDate() + i);
        const dStart = new Date(d);
        dStart.setHours(0, 0, 0, 0);
        const isFuture = dStart > today;

        const m = getDailyMetabolicMetrics(d);
        const dayLabel = `${dayLabels[i]} ${d.getDate()}`;
        weekStats.push({ label: dayLabel, ...m, date: d, isFuture });

        if (isFuture) {
            // Días que aún no transcurrieron: NUNCA en ámbar de error. Barra neutra sutil de planificación
            barColors.push('rgba(255, 255, 255, 0.05)');
            borderColors.push('rgba(255, 255, 255, 0.12)');
        } else {
            // Lógica adaptable según el objetivo (Déficit vs Superávit)
            let isOptimal = false;
            if (isMuscleGain) {
                // Hipertrofia: Superávit objetivo (+150 a +550 kcal)
                isOptimal = (m.netBalance >= 150 && m.netBalance <= 550);
            } else {
                // Pérdida de grasa: Déficit objetivo (-200 a -750 kcal)
                isOptimal = (m.netBalance <= -200 && m.netBalance >= -750);
            }

            if (isOptimal) {
                // Objetivo cumplido: Siempre Champagne Gold
                barColors.push('rgba(229, 203, 167, 0.85)');
                borderColors.push('#E5CBA7');
            } else {
                // Fuera del objetivo pautado: Ámbar / Arena suave
                barColors.push('rgba(217, 119, 6, 0.75)');
                borderColors.push('#D97706');
            }
        }
    }

    // Calcular límites simétricos para centrar el 0 en el medio exacto del eje Y
    const maxVal = Math.max(600, ...weekStats.map(s => Math.abs(s.netBalance || 0)));
    const yLimit = Math.ceil((maxVal * 1.25) / 100) * 100;

    if (window._sensWeeklyBalanceChart) {
        window._sensWeeklyBalanceChart.destroy();
    }

    try {
        const ctx = canvas.getContext('2d');
        window._sensWeeklyBalanceChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: weekStats.map(s => s.label),
                datasets: [{
                    data: weekStats.map(s => s.netBalance),
                    backgroundColor: barColors,
                    borderColor: borderColors,
                    borderWidth: 1,
                    borderRadius: 4,
                    borderSkipped: false,
                    maxBarThickness: 22,
                    barPercentage: 0.5
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                layout: {
                    padding: { top: 6, bottom: 0, left: 0, right: 0 }
                },
                plugins: {
                    legend: { display: false },
                    tooltip: {
                        backgroundColor: '#09090B',
                        titleColor: '#FFFFFF',
                        titleFont: { family: 'Plus Jakarta Sans', size: 11, weight: '700' },
                        bodyColor: '#E5CBA7',
                        bodyFont: { family: 'Plus Jakarta Sans', size: 10.5 },
                        padding: 9,
                        cornerRadius: 8,
                        displayColors: false,
                        callbacks: {
                            label: function(context) {
                                const item = weekStats[context.dataIndex];
                                if (item.isFuture) {
                                    return [
                                        `Planificado: ${userGoal === 'muscle_gain' ? '+300' : '-400'} kcal`,
                                        `Día aún no transcurrido`
                                    ];
                                }
                                const sign = item.netBalance > 0 ? '+' : '';
                                return [
                                    `Balance: ${sign}${item.netBalance} kcal`,
                                    `Ingesta: ${item.targetIntake} kcal • Gasto: ${item.tdee} kcal`
                                ];
                            }
                        }
                    }
                },
                scales: {
                    x: {
                        grid: { display: false },
                        ticks: {
                            color: '#A1A1AA',
                            font: { family: 'Plus Jakarta Sans', size: 10, weight: '700' }
                        }
                    },
                    y: {
                        min: -yLimit,
                        max: yLimit,
                        grid: {
                            color: (context) => (context.tick && context.tick.value === 0) ? 'rgba(229, 203, 167, 0.45)' : 'rgba(255, 255, 255, 0.05)',
                            lineWidth: (context) => (context.tick && context.tick.value === 0) ? 1.5 : 1
                        },
                        ticks: {
                            color: (context) => (context.tick && context.tick.value === 0) ? '#E5CBA7' : '#A1A1AA',
                            font: { family: 'Plus Jakarta Sans', size: 9 },
                            callback: function(val) {
                                return (val > 0 ? '+' : '') + val;
                            }
                        }
                    }
                }
            }
        });
    } catch (e) {
        console.warn('Error al renderizar el gráfico semanal de balance:', e);
    }
}

/**
 * Actualiza la Card de Balance Energético con los valores reales del día y el gráfico semanal
 */
function updateObjectiveCardData(selectedDate = null, isDraftLiveUpdate = false) {
    if (!selectedDate) {
        selectedDate = AppState.selectedDate || new Date();
    }

    const dateLabel = document.getElementById('dashBalanceDateLabel');
    const goalPill = document.getElementById('dashObjectiveGoalPill');
    const ingestaNum = document.getElementById('dashIngestaNum');
    const tdeeNum = document.getElementById('dashTdeeNum');
    const netValEl = document.getElementById('dashNetDeficitVal');
    const statusTextEl = document.getElementById('dashBalanceStatusText');
    const breakdownEl = document.getElementById('dashBalanceBurnBreakdown');
    const graphGoalTarget = document.getElementById('dashGraphGoalTarget');
    const mealsSubEl = document.getElementById('dashBalanceMealsCount');
    const btnGoTracking = document.getElementById('btnGoTrackingFromBalance');

    const metrics = getDailyMetabolicMetrics(selectedDate);
    const profile = AppState.profile || {};
    const userGoal = profile.goal || 'fat_loss';
    const isMuscleGain = userGoal === 'muscle_gain';

    const stepsInput = document.getElementById('dashStepsInput');
    const cardioInput = document.getElementById('dashCardioInput');
    const activeBtn = document.querySelector('#dashCardioTypesGrid .sens-cardio-type-btn.active');

    let liveSteps = metrics.dailySteps;
    let liveCardioMins = metrics.cardioMinutes;
    let liveCardioType = metrics.cardioType;
    let liveCardioRate = metrics.cardioRate;

    if (isDraftLiveUpdate) {
        if (stepsInput) {
            liveSteps = Math.max(0, parseInt(stepsInput.value, 10) || 0);
        }
        if (cardioInput) {
            liveCardioMins = Math.max(0, parseInt(cardioInput.value, 10) || 0);
        }
        if (activeBtn) {
            liveCardioType = activeBtn.getAttribute('data-type') || 'caminata';
            liveCardioRate = parseFloat(activeBtn.getAttribute('data-rate')) || 6.5;
        }
    } else {
        if (stepsInput) {
            stepsInput.value = metrics.dailySteps;
        }
        if (cardioInput) {
            cardioInput.value = metrics.cardioMinutes;
        }
        document.querySelectorAll('#dashCardioTypesGrid .sens-cardio-type-btn').forEach(btn => {
            const type = btn.getAttribute('data-type');
            btn.classList.toggle('active', type === metrics.cardioType);
        });
        document.querySelectorAll('.sens-act-quick-chip').forEach(c => {
            const chipVal = parseInt(c.textContent.replace('.', '').replace(',', ''), 10) || 0;
            c.classList.toggle('active', chipVal > 0 && chipVal === metrics.dailySteps);
        });
    }

    const weight = metrics.weight || 75;
    const liveStepsBurn = Math.round(liveSteps * (weight * 0.00052));
    const liveCardioBurn = Math.round(liveCardioMins * liveCardioRate);
    const liveActiveBurn = metrics.workoutBurn + liveStepsBurn + liveCardioBurn;
    const liveTdee = metrics.bmr + liveActiveBurn;
    const liveNetBalance = metrics.targetIntake - liveTdee;

    if (dateLabel) {
        const d = selectedDate || AppState.selectedDate || new Date();
        const formatted = d.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });
        dateLabel.textContent = formatted.charAt(0).toUpperCase() + formatted.slice(1);
    }

    if (goalPill) {
        goalPill.textContent = isMuscleGain ? 'Meta: +300 kcal' : 'Meta: -400 kcal';
        goalPill.style.background = 'rgba(229, 203, 167, 0.12)';
        goalPill.style.color = '#E5CBA7';
        goalPill.style.borderColor = 'rgba(229, 203, 167, 0.3)';
    }

    if (graphGoalTarget) {
        graphGoalTarget.textContent = isMuscleGain ? '+300 kcal/día' : '-400 kcal/día';
    }

    if (ingestaNum) {
        ingestaNum.textContent = metrics.targetIntake.toLocaleString('es-AR');
    }

    if (mealsSubEl) {
        const athId = getActiveAthleteId();
        const dateKey = getFormattedDateKey(selectedDate);
        const logKey = `sens_user_consumed_foods_${athId}_${dateKey}`;
        let count = 0;
        try {
            const logged = JSON.parse(localStorage.getItem(logKey) || '{}');
            count = Object.keys(logged).length;
        } catch (e) {}
        mealsSubEl.textContent = count > 0 ? `${count} ${count === 1 ? 'comida' : 'comidas'}` : '0 comidas';
    }

    if (tdeeNum) {
        tdeeNum.textContent = liveTdee.toLocaleString('es-AR');
    }

    if (breakdownEl) {
        breakdownEl.textContent = `Basal: ${metrics.bmr.toLocaleString('es-AR')} • Activo: ${liveActiveBurn.toLocaleString('es-AR')}`;
    }

    // Actualizar Panel Táctil de Actividad Diaria (Pasos & Cardio)
    const activeBurnBadge = document.getElementById('dashActiveBurnBadge');
    if (activeBurnBadge) {
        activeBurnBadge.textContent = `+${liveActiveBurn.toLocaleString('es-AR')} kcal`;
    }

    const stepsSubBurn = document.getElementById('dashStepsSubBurn');
    if (stepsSubBurn) {
        stepsSubBurn.textContent = `~${liveStepsBurn} kcal`;
    }

    const cardioSubBurn = document.getElementById('dashCardioSubBurn');
    if (cardioSubBurn) {
        cardioSubBurn.textContent = `~${liveCardioBurn} kcal`;
    }

    const netBoxEl = document.getElementById('dashBalanceNetBox');
    const heroCol = netBoxEl?.querySelector('.sens-triptych-col.hero');
    if (netValEl) {
        const sign = liveNetBalance > 0 ? '+' : '';
        netValEl.innerHTML = `${sign}${liveNetBalance.toLocaleString('es-AR')}<span class="unit">kcal</span>`;
    }

    if (statusTextEl) {
        const isOptimal = isMuscleGain ? (liveNetBalance >= 150) : (liveNetBalance <= -300);
        if (isOptimal) {
            statusTextEl.textContent = isMuscleGain ? 'Superávit Cumplido' : 'Déficit Logrado';
            statusTextEl.style.color = '#E5CBA7';
            if (netValEl) netValEl.style.color = '#E5CBA7';
            if (heroCol) {
                heroCol.style.borderColor = 'rgba(229, 203, 167, 0.35)';
                heroCol.style.background = 'rgba(229, 203, 167, 0.08)';
            }
        } else {
            statusTextEl.textContent = liveNetBalance > 0 ? 'Superávit Elevado' : 'Ajuste Requerido';
            statusTextEl.style.color = '#D97706';
            if (netValEl) netValEl.style.color = '#D97706';
            if (heroCol) {
                heroCol.style.borderColor = 'rgba(217, 119, 6, 0.35)';
                heroCol.style.background = 'rgba(217, 119, 6, 0.08)';
            }
        }
    }

    if (!isDraftLiveUpdate) {
        // Actualizar Racha SENS & Cumplimiento de 3 Pilares con datos guardados
        if (typeof updateSensStreakCard === 'function') {
            updateSensStreakCard(selectedDate);
        }
        // Renderizar gráfico semanal
        renderWeeklyBalanceChart(selectedDate);
    }

    // Sincronizar card de biometría si estuviese visible
    if (typeof updateBiometricsCardData === 'function') {
        updateBiometricsCardData(selectedDate);
    }

    // Listener para calibrar pasos y cardio
    if (btnGoTracking) {
        btnGoTracking.onclick = (e) => {
            if (e) e.stopPropagation();
            if (typeof window.scrollToBalanceCard === 'function') {
                window.scrollToBalanceCard();
            }
        };
    }
}
window.updateObjectiveCardData = updateObjectiveCardData;

/**
 * Actualiza la Card de Composición Corporal & Peso (#dashBiometricsCard)
 */
function updateBiometricsCardData(selectedDate = null) {
    const currentWeightEl = document.getElementById('dashBioCurrentWeight');
    const targetWeightEl = document.getElementById('dashBioTargetWeight');
    const weightDeltaEl = document.getElementById('dashBioWeightDelta');
    const currentMuscleEl = document.getElementById('dashBioCurrentMuscle');
    const targetMuscleEl = document.getElementById('dashBioTargetMuscle');
    const currentFatEl = document.getElementById('dashBioCurrentFat');
    const targetFatEl = document.getElementById('dashBioTargetFat');
    const initialWeightEl = document.getElementById('dashBioInitialWeight');
    const targetWeightBarEl = document.getElementById('dashBioTargetWeightBar');
    const progressBar = document.getElementById('dashBioProgressBar');
    const progressPct = document.getElementById('dashBioProgressPct');
    const lastLoggedDate = document.getElementById('dashBioLastLoggedDate');
    const bioDateLabel = document.getElementById('dashBioDateLabel');
    const btnGoBio = document.getElementById('btnGoTrackingFromBio');

    const d = selectedDate || AppState.selectedDate || new Date();
    const isToday = isSameDay(d, new Date());

    if (bioDateLabel) {
        const formatted = d.toLocaleDateString('es-AR', { day: 'numeric', month: 'long' });
        bioDateLabel.textContent = `Registro al ${formatted}`;
    }

    const profile = AppState.profile || {};
    const anamnesis = AppState.anamnesis || {};
    const athId = getActiveAthleteId();
    const isDemo = (athId === 'usr-vip-001' || athId === 'mock_vip');

    const weightRaw = profile.current_weight || anamnesis.weight;
    const currentWeight = weightRaw ? parseFloat(weightRaw) : (isDemo ? 75.8 : 76.0);
    const initialWeight = profile.initial_weight || anamnesis.initial_weight || (isDemo ? 82.0 : 80.0);
    const targetWeight = profile.target_weight || anamnesis.target_weight || (isDemo ? 72.0 : 70.0);

    const muscleRaw = profile.muscle_mass || anamnesis.muscle_mass;
    const currentMuscle = muscleRaw ? parseFloat(muscleRaw) : (isDemo ? 35.2 : 34.0);
    const targetMuscle = profile.target_muscle_mass || (isDemo ? 36.5 : 36.0);

    const fatRaw = profile.body_fat || anamnesis.body_fat;
    const currentFat = fatRaw ? parseFloat(fatRaw) : (isDemo ? 13.8 : 15.0);
    const targetFat = profile.target_body_fat || (isDemo ? 11.5 : 12.0);

    if (currentWeightEl) currentWeightEl.textContent = currentWeight.toFixed(1);
    if (targetWeightEl) targetWeightEl.textContent = `${targetWeight.toFixed(1)} kg`;
    if (currentMuscleEl) currentMuscleEl.textContent = currentMuscle.toFixed(1);
    if (targetMuscleEl) targetMuscleEl.textContent = `${targetMuscle.toFixed(1)} kg`;
    if (currentFatEl) currentFatEl.textContent = currentFat.toFixed(1);
    if (targetFatEl) targetFatEl.textContent = `${targetFat.toFixed(1)}%`;

    if (weightDeltaEl) {
        const totalDelta = currentWeight - initialWeight;
        const sign = totalDelta > 0 ? '+' : '';
        weightDeltaEl.textContent = `${sign}${totalDelta.toFixed(1)} kg vs inicio`;
    }

    if (initialWeightEl) initialWeightEl.textContent = `${initialWeight.toFixed(1)} kg`;
    if (targetWeightBarEl) targetWeightBarEl.textContent = `${targetWeight.toFixed(1)} kg`;

    if (progressBar && progressPct) {
        const totalToLose = Math.abs(initialWeight - targetWeight);
        const lostSoFar = Math.abs(initialWeight - currentWeight);
        const pct = totalToLose > 0 ? Math.min(100, Math.max(5, Math.round((lostSoFar / totalToLose) * 100))) : 68;
        progressBar.style.width = `${pct}%`;
        progressPct.textContent = `${pct}% completado`;
    }

    if (lastLoggedDate) {
        lastLoggedDate.textContent = isToday ? `Último pesaje: Hoy 08:30 hs` : `Último pesaje: ${formatDateDDMM(d)}`;
    }

    if (btnGoBio) {
        btnGoBio.onclick = (e) => {
            if (e) e.stopPropagation();
            const card = document.getElementById('dashBiometricsCard');
            if (typeof triggerCardSpringAndNavigate === 'function') {
                triggerCardSpringAndNavigate(card, () => {
                    switchPortalView('trackingView');
                });
            } else if (typeof switchPortalView === 'function') {
                switchPortalView('trackingView');
            }
        };
    }
}

/**
 * Inicializa el Modal Rápido de Carga de Peso & Pasos
 */
function initQuickBiometricsModal() {
    const modal = document.getElementById('quickBiometricsModal');
    const openBtn = document.getElementById('btnOpenQuickBioModal');
    const closeBtn = document.getElementById('btnCloseQuickBioModal');
    const form = document.getElementById('quickBioForm');
    const weightInp = document.getElementById('quickInputWeight');
    const muscleInp = document.getElementById('quickInputMuscle');
    const fatInp = document.getElementById('quickInputFat');
    const stepsInp = document.getElementById('quickInputSteps');

    if (!modal) return;

    if (openBtn) {
        openBtn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const profile = AppState.profile || {};
            const anamnesis = AppState.anamnesis || {};
            if (weightInp) weightInp.value = profile.current_weight || anamnesis.weight || '75.8';
            if (muscleInp) muscleInp.value = profile.muscle_mass || '35.2';
            if (fatInp) fatInp.value = profile.body_fat || anamnesis.body_fat || '13.8';
            if (stepsInp) stepsInp.value = AppState.dailySteps || '8500';
            modal.style.display = 'flex';
        });
    }

    if (closeBtn) {
        closeBtn.addEventListener('click', () => {
            modal.style.display = 'none';
        });
    }

    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            modal.style.display = 'none';
        }
    });

    if (form) {
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const w = parseFloat(weightInp?.value);
            const m = parseFloat(muscleInp?.value);
            const f = parseFloat(fatInp?.value);
            const s = parseInt(stepsInp?.value, 10);

            if (!AppState.profile) AppState.profile = {};
            if (!isNaN(w) && w > 0) AppState.profile.current_weight = w;
            if (!isNaN(m) && m > 0) AppState.profile.muscle_mass = m;
            if (!isNaN(f) && f > 0) AppState.profile.body_fat = f;
            if (!isNaN(s) && s > 0) AppState.dailySteps = s;

            const athId = getActiveAthleteId();
            localStorage.setItem(`sens_profile_${athId}`, JSON.stringify(AppState.profile));

            modal.style.display = 'none';
            if (typeof showSensToast === 'function') {
                showSensToast('Métricas actualizadas con éxito.', 'champagne');
            }

            // Actualizar reactivamente todas las tarjetas
            if (typeof updateObjectiveCardData === 'function') updateObjectiveCardData();
            if (typeof updateBiometricsCardData === 'function') updateBiometricsCardData();
        });
    }
}

/**
 * MÓDULO D: Floating Dock Inferior Móvil (Estilo BIGG / Samsung Health)
 */
function initFloatingDock() {
    const isPortal = document.body.classList.contains('in-portal') || document.documentElement.classList.contains('in-portal-mode');
    const athleteDock = document.getElementById('sensFloatingDock');
    const coachDock = document.getElementById('sensCoachFloatingDock');
    const isAdmin = typeof isCurrentUserAdmin === 'function' && isCurrentUserAdmin();
    const inCoach = document.body.classList.contains('in-coach-mode') || document.body.getAttribute('data-active-view') === 'coachHubView';

    if (athleteDock) {
        if (!isPortal || inCoach) {
            athleteDock.style.display = 'none';
        } else {
            athleteDock.style.display = 'grid';
        }
    }
    if (coachDock) {
        if (isPortal && inCoach && isAdmin) {
            coachDock.style.display = 'grid';
        } else {
            coachDock.style.display = 'none';
        }
    }

    // Direct event listeners on athlete dock buttons (Fast click / Touchend)
    if (athleteDock && !athleteDock._hasDockBound) {
        athleteDock._hasDockBound = true;
        
        athleteDock.querySelectorAll('.sens-dock-item[data-dock-tab]').forEach(btn => {
            const handleNav = (e) => {
                if (e) {
                    e.preventDefault();
                    e.stopPropagation();
                }
                const targetTab = btn.getAttribute('data-dock-tab');
                if (targetTab && typeof switchPortalView === 'function') {
                    switchPortalView(targetTab);
                    window.scrollTo({ top: 0, behavior: 'instant' });
                }
            };
            btn.addEventListener('click', handleNav);
            btn.addEventListener('touchend', (e) => {
                handleNav(e);
            }, { passive: false });
        });
    }

    // Direct event listeners on coach dock buttons
    if (coachDock && !coachDock._hasCoachDockBound) {
        coachDock._hasCoachDockBound = true;

        coachDock.querySelectorAll('.coach-dock-btn[data-coach-subtab]').forEach(btn => {
            const handleCoachNav = (e) => {
                if (e) {
                    e.preventDefault();
                    e.stopPropagation();
                }
                const subtab = btn.getAttribute('data-coach-subtab');
                if (subtab && typeof switchCoachSubTab === 'function') {
                    switchCoachSubTab(subtab);
                }
            };
            btn.addEventListener('click', handleCoachNav);
            btn.addEventListener('touchend', (e) => {
                handleCoachNav(e);
            }, { passive: false });
        });
    }

    // Global delegation fallback directly on docks or document
    if (!window._hasSensFloatingDockDelegated) {
        window._hasSensFloatingDockDelegated = true;

        const onDockClick = (e) => {
            const athBtn = e.target.closest('#sensFloatingDock .sens-dock-item[data-dock-tab], .sens-floating-dock:not(.coach-mode-dock) .sens-dock-item[data-dock-tab]');
            if (athBtn) {
                e.preventDefault();
                e.stopPropagation();
                const tab = athBtn.getAttribute('data-dock-tab');
                if (tab && typeof switchPortalView === 'function') {
                    switchPortalView(tab);
                    window.scrollTo({ top: 0, behavior: 'instant' });
                }
                return;
            }

            const coachBtn = e.target.closest('#sensCoachFloatingDock .coach-dock-btn[data-coach-subtab], .coach-mode-dock .coach-dock-btn[data-coach-subtab]');
            if (coachBtn) {
                e.preventDefault();
                e.stopPropagation();
                const subtab = coachBtn.getAttribute('data-coach-subtab');
                if (subtab && typeof switchCoachSubTab === 'function') {
                    switchCoachSubTab(subtab);
                }
                return;
            }
        };

        document.addEventListener('click', onDockClick);
        document.addEventListener('touchend', onDockClick, { passive: false });
    }
}

/**
 * MÓDULO E: Sincronización de Triggers de Alumnos del Coach OS
 */
function initCoachAthletePickerTriggers() {
    document.querySelectorAll('.btn-trigger-athlete-sheet').forEach(btn => {
        if (btn._hasSheetTrigger) return;
        btn._hasSheetTrigger = true;
        btn.addEventListener('click', (e) => {
            if (!isCurrentUserAdmin()) {
                e.preventDefault();
                e.stopPropagation();
                return;
            }
            e.preventDefault();
            e.stopPropagation();
            if (typeof window.openAthleteSheet === 'function') {
                window.openAthleteSheet();
            }
        });
    });
}

